    inline bool Readable(const void* pointer, size_t size)
    {
        auto cursor = reinterpret_cast<uintptr_t>(pointer);
        if (!cursor || size > UINTPTR_MAX - cursor) return false;
        const auto limit = cursor + size;
        while (cursor < limit)
        {
            MEMORY_BASIC_INFORMATION region{};
            if (!VirtualQuery(reinterpret_cast<const void*>(cursor), &region, sizeof(region)) || region.State != MEM_COMMIT
                || (region.Protect & (PAGE_GUARD | PAGE_NOACCESS))) return false;
            constexpr DWORD readable = PAGE_READONLY | PAGE_READWRITE | PAGE_WRITECOPY | PAGE_EXECUTE_READ | PAGE_EXECUTE_READWRITE | PAGE_EXECUTE_WRITECOPY;
            if (!(region.Protect & readable)) return false;
            auto next = reinterpret_cast<uintptr_t>(region.BaseAddress) + region.RegionSize;
            if (next <= cursor) return false;
            cursor = next;
        }
        return true;
    }
    template<class T> T Read(const void* base, size_t offset = 0)
    {
        T result{};
        auto address = reinterpret_cast<uintptr_t>(base);
        if (!address || offset > UINTPTR_MAX - address) return result;
        auto* field = reinterpret_cast<const void*>(address + offset);
        if (Readable(field, sizeof(result))) std::memcpy(&result, field, sizeof(result));
        return result;
    }
